/**
 * v5.6 观战深链：大厅网页的「观战」按钮给的是 `?room=CODE&spectate=1`。
 * 只有同一 URL 里带 room 才有意义（调用侧一并判断）；值为 '1' / 'true' 才算数。
 * @param {string} search e.g. location.search
 * @returns {boolean}
 */
export function parseSpectateParam(search) {
  try {
    const raw = new URLSearchParams(search || '').get('spectate');
    return raw === '1' || raw === 'true';
  } catch {
    return false;
  }
}

